from vision_client import VisionClient
from vision_models import ImagePayload, TextDetectionResponse, TextDetectionResult


def detect_image_text(payload: ImagePayload, config=None) -> TextDetectionResponse:
    config = config or {}
    region_name = config.get("region")
    client = VisionClient(region_name)

    response = client.rekognition_client.detect_text(
        Image={"Bytes": payload.image_bytes}
    )

    text_detections = []
    for text in response["TextDetections"]:
        if text["Type"] == "WORD" or text["Type"] == "LINE": # Consider both words and lines
            geometry = text["Geometry"]["BoundingBox"]
            text_detections.append(
                TextDetectionResult(
                    text=text["DetectedText"],
                    confidence=text["Confidence"] / 100.0,
                    type=text["Type"],
                    bounding_box={
                        "left": geometry["Left"],
                        "top": geometry["Top"],
                        "width": geometry["Width"],
                        "height": geometry["Height"],
                    },
                )
            )

    return TextDetectionResponse(text_detections=text_detections)

from vision_client import VisionClient
from vision_models import ImagePayload, SafetyScoreResponse, ModerationLabel


def score_image_safety(payload: ImagePayload, config=None) -> SafetyScoreResponse:
    config = config or {}
    region_name = config.get("region")
    client = VisionClient(region_name)

    response = client.rekognition_client.detect_moderation_labels(
        Image={"Bytes": payload.image_bytes},
        MinConfidence=float(config.get("min_confidence", 60.0))
    )

    moderation_labels = []
    for label in response["ModerationLabels"]:
        moderation_labels.append(
            ModerationLabel(
                name=label["ParentName"] + "/" + label["Name"] if label.get("ParentName") else label["Name"],
                confidence=label["Confidence"] / 100.0,
            )
        )

    return SafetyScoreResponse(moderation_labels=moderation_labels)

from vision_client import VisionClient
from vision_models import TranslationRequest, TranslationResponse


def alt_text_translate(payload: TranslationRequest, config=None) -> TranslationResponse:
    config = config or {}
    region_name = config.get("region")
    client = VisionClient(region_name)

    response = client.translate_client.translate_text(
        Text=payload.text,
        SourceLanguageCode=payload.source_language_code,
        TargetLanguageCode=payload.target_language_code,
    )

    return TranslationResponse(translated_text=response["TranslatedText"])
